    int trueCarry = carryVal - 50;
    if (idx == 17) {
        if (pCount + nCount + trueCarry == 0) {
            return 0;
        }
        return MAX_INF;
    }
    if (memoTable[idx][pCount][nCount][carryVal] != -1)
        return memoTable[idx][pCount][nCount][carryVal];
    int minRes = MAX_INF;
    for (int p = 0; p <= min(15, pCount); p++) {
        for (int n = 0; n <= min(15, nCount); n++) {
            int sum = pCount - nCount + trueCarry;
            int digit = ((sum % 10) + 10) % 10;
            int nextCarry = (sum > 0) ? (sum / 10) : ((sum - 9) / 10);
            if (digit != (numStrRev[idx] - '0'))
