        }
    }
    return memoTable[idx][pCount][nCount][carryVal] = minRes;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long inputNumber;
    cin >> inputNumber;
    int sizeLimit = 50;
